public class BrightnessSliderScreen extends Screen {
    private static double brightness = 0.5;
    private SliderWidget slider;

    public BrightnessSliderScreen() {
        super(Component.literal("Brightness"));
    }

    public static double getBrightness() { return brightness; }

    @Override
    protected void init() {
        slider = addRenderableWidget(new SliderWidget(width / 2 - 100, 40, 200, 20));
        addRenderableWidget(Button.builder(Component.literal("Reset"), b -> {
            brightness = 0.5;
