        protected void updateMessage() {
            setMessage(Component.literal("Brightness: "
                    + (int) Math.round(value * 100) + "%"));
        }

        @Override
        protected void applyValue() {
            brightness = value;
        }

        void refresh() {
            this.value = brightness;
            updateMessage();
            applyValue();
        }
    }
}

