package com.example.examplemod.client;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

import java.util.List;

public class TeleportsListScreen extends Screen {
    private static final int ROWS = 8;
    private final List<String> entries = List.of(
            "home", "mine", "farm", "nether_hub", "end_gate",
            "shop", "arena", "storage", "villagers", "outpost");
    private int scrollOffset = 0;
    private int hoveredRow = -1;

    public TeleportsListScreen() {
        super(Component.literal("Teleports"));
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY,
                                 double xAmount, double yAmount) {
        int max = Math.max(0, entries.size() - ROWS);
        scrollOffset = Math.clamp(scrollOffset - (int) Math.signum(yAmount), 0, max);
        return true;
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        g.drawCenteredString(font, entries.size() + "/" + entries.size(),
                width / 2, 24, 0xAAAAAA);
        hoveredRow = -1;
        int y = 40;
        for (int i = 0; i < ROWS && scrollOffset + i < entries.size(); i++) {
            boolean hovered = mouseY >= y && mouseY < y + 12
                    && mouseX >= width / 2 - 100 && mouseX < width / 2 + 100;
            if (hovered) hoveredRow = i;
            g.drawString(font, entries.get(scrollOffset + i), width / 2 - 100, y,
                    hovered ? 0xFFFF55 : 0xFFFFFF);
            y += 12;
        }
        super.render(g, mouseX, mouseY, partialTick);
    }

    @Override
    protected void init() {
        addRenderableWidget(Button.builder(Component.literal("Close"), b -> onClose())
                .bounds(width / 2 - 50, height - 28, 100, 20).build());
    }
}

