public class WikiTabsScreen extends Screen {
    private static final String[] TABS = {"Basics", "Crafting", "Commands"};
    private static final String[][] CONTENT = {
            {"Place blocks with RMB.", "Break blocks with LMB."},
            {"3 planks -> crafting table.", "Sticks from 2 planks."},
            {"/time set day", "/weather clear"}
    };
    private int activeTab = 0;

    public WikiTabsScreen() {
        super(Component.literal("Wiki"));
    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        for (int i = 0; i < TABS.length; i++) {
            int tx = width / 2 - 150 + i * 100;
            if (mouseX >= tx && mouseX <= tx + 90
                    && mouseY >= 24 && mouseY <= 36) {
                activeTab = i;
                return true;
            }
        }
        return super.mouseClicked(mouseX, mouseY, button);
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        for (int i = 0; i < TABS.length; i++) {
            int tx = width / 2 - 150 + i * 100;
            g.drawString(font, TABS[i], tx, 24,
                    i == activeTab ? 0xFFFF55 : 0x888888);
        }
        int y = 48;
        for (String line : CONTENT[activeTab]) {
            g.drawString(font, line, width / 2 - 120, y, 0xFFFFFF);
            y += 12;
        }
        super.render(g, mouseX, mouseY, partialTick);
