package com.example.examplemod.network;

import io.netty.buffer.ByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;

public record LeaderboardRequestPayload(int page)
        implements CustomPacketPayload {

    public static final Type<LeaderboardRequestPayload> TYPE =
            new Type<>(ResourceLocation.fromNamespaceAndPath(
                    "examplemod", "leaderboard_request"));

    public static final StreamCodec<ByteBuf, LeaderboardRequestPayload> STREAM_CODEC =
            StreamCodec.composite(
                    ByteBufCodecs.VAR_INT, LeaderboardRequestPayload::page,
                    LeaderboardRequestPayload::new);

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }

    public static void handleServer(LeaderboardRequestPayload payload,
                                    net.neoforged.neoforge.network.handling.                                            IPayloadContext context) {
        if (payload.page < 0 || payload.page > 100) {
            return; // invalid client input: silently ignore
        }
    }
}

package com.example.examplemod.client;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

import com.example.examplemod.network.LeaderboardRequestPayload;

public class LeaderboardScreen extends Screen {
    private boolean sent;
    private String[] lines = new String[0];
    private boolean dataReady;

    public LeaderboardScreen() {
        super(Component.literal("Leaderboard"));
    }

    public static void acceptData(String[] data) {
        if (data == null) return;
        LeaderboardScreen screen = current;
        if (screen != null) {
            screen.lines = data;
            screen.dataReady = true;
        }
    }

    private static LeaderboardScreen current;

    @Override
    protected void init() {
        current = this;
        if (!sent) {
            sent = true;
            NetworkHelper.sendToServer(new LeaderboardRequestPayload(0));
        }
    }

    @Override
    public void removed() {
        current = null;
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        if (!dataReady) {
            g.drawCenteredString(font, "Loading...", width / 2, height / 2, 0xFFAAAAAA);
        } else {
            int y = 40;
            for (String line : lines) {
                g.drawString(font, line, width / 2 - 100, y, 0xFFFFFF);
                y += 12;
            }
        }
        super.render(g, mouseX, mouseY, partialTick);
    }
}

