import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload.Type;
import net.minecraft.resources.ResourceLocation;

public record PingPayload(long clientTime) implements CustomPacketPayload {

    public static final Type<PingPayload> TYPE =
            new Type<>(ResourceLocation.fromNamespaceAndPath("examplemod", "ping"));

    public static final StreamCodec<ByteBuf, PingPayload> STREAM_CODEC =
            StreamCodec.composite(
                    ByteBufCodecs.VAR_LONG, PingPayload::clientTime,
                    PingPayload::new);

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }

    private static volatile PingPayload lastReceived;

    public static PingPayload lastReceived() {
        return lastReceived;
    }

    public static void handleClient(PingPayload payload,
                                    net.neoforged.neoforge.network.handling.                                            IPayloadContext context) {
        lastReceived = payload;
    }
}

