public class AdaptiveGridScreen extends Screen {
    public static int lastColumns = -1;
    private static final int CELLS = 12;

    public AdaptiveGridScreen() {
        super(Component.literal("Grid"));
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        int columns = Math.clamp(width / 24, 2, 6);
        lastColumns = columns;
        int rows = (CELLS + columns - 1) / columns;
        int totalW = columns * 24 - 4;
        int totalH = rows * 24 - 4;
