            g.fill(cx - 1, cy - 1, cx + 21, cy + 21, 0xFF666666);
            g.fill(cx, cy, cx + 20, cy + 20, 0xFF333333);
        }
        super.render(g, mouseX, mouseY, partialTick);
    }
}

package com.example.examplemod.client;

import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.FormattedText;

import java.util.ArrayList;
import java.util.List;

public class SafeTextScreen extends Screen {
    public record TextRow(String text, boolean truncated) {}

    public SafeTextScreen() {
        super(Component.literal("Safe text"));
    }

    public static List<TextRow> buildRows(Font font, String text) {
        List<TextRow> rows = new ArrayList<>();
        if (font.width(text) <= 120) {
            rows.add(new TextRow(text, false));
            return rows;
        }
        List<FormattedText> wrapped = font.split(FormattedText.of(text), 120);
        for (int i = 0; i < Math.min(2, wrapped.size()); i++) {
            String s = wrapped.get(i).getString();
            boolean truncated = i == 1 && wrapped.size() > 2;
            if (truncated) s = s + "...";
            rows.add(new TextRow(s, truncated));
        }
        return rows;
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        int y = 40;
        for (int i = 1; i <= 3; i++) {
            for (TextRow row : buildRows(font,
                    Component.translatable("key.exmod.line_" + i).getString())) {
                g.drawString(font, row.text(), width / 2 - 60, y, 0xFFFFFF);
                y += 12;
            }
        }
        super.render(g, mouseX, mouseY, partialTick);
    }
}

