public class PagedDocScreen extends Screen {
    private static final String[][] PAGES = {
            {"Page 1: intro", "more text"},
            {"Page 2: usage"},
            {"Page 3: rules", "line B", "line C"},
            {"Page 4: credits"}
    };
    private int page;
    private Button prev;
    private Button next;

    public PagedDocScreen() {
        super(Component.literal("Doc"));
    }

    @Override
    protected void init() {
        prev = addRenderableWidget(Button.builder(Component.literal("<"), b -> {
            if (page > 0) page--;
            updateButtons();
        }).bounds(10, height - 28, 60, 20).build());
        next = addRenderableWidget(Button.builder(Component.literal(">"), b -> {
            if (page < PAGES.length - 1) page++;
            updateButtons();
        }).bounds(width - 70, height - 28, 60, 20).build());
