public class SettingsWizardScreen extends Screen {
    private static final String[] QUESTIONS = {"wizard.q_1", "wizard.q_2", "wizard.q_3"};
    private int step;
    private final boolean[] answers = new boolean[3];

    public SettingsWizardScreen() {
        super(Component.literal("Wizard"));
    }

    public boolean[] answers() {
        return answers;
    }

    @Override
    protected void init() {
        addWidgets();
    }

    private void addWidgets() {
        addRenderableWidget(CycleButton.onOffBuilder(answers[step])
                .create(width / 2 - 100, 60, 200, 20,
                        Component.translatable(QUESTIONS[step]),
                        (btn, val) -> answers[step] = val));
        addRenderableWidget(Button.builder(Component.literal("Back"), b -> {
            if (step > 0) step--;
            rebuild();
        }).bounds(width / 2 - 100, height - 48, 98, 20).build());
        boolean last = step == QUESTIONS.length - 1;
        addRenderableWidget(Button.builder(
                        Component.literal(last ? "Finish" : "Next"), b -> {
                            if (last) onClose();
                            else {
                                step++;
                                rebuild();
                            }
                        })
                .bounds(width / 2 + 2, height - 48, 98, 20).build());
    }

    private void rebuild() {
        clearWidgets();
        addWidgets();
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        g.drawCenteredString(font, "Step " + (step + 1) + " of 3",
