package com.example.examplemod.client;

import net.minecraft.client.gui.Font;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.FormattedText;

import java.util.ArrayList;
import java.util.List;

public class DpiSafeTextScreen extends Screen {
    public DpiSafeTextScreen() {
        super(Component.literal("Docs"));
    }

    public static List<String> wrap(Font font, String text, int maxWidth) {
        List<String> out = new ArrayList<>();
        for (FormattedText ft : font.split(FormattedText.of(text), maxWidth)) {
            out.add(ft.getString());
        }
        return out;
    }

    @Override
    public void render(GuiGraphics g, int mouseX, int mouseY, float partialTick) {
        renderBackground(g, mouseX, mouseY, partialTick);
        String text = Component.translatable("exmod.docs.long").getString();
        int wide = Math.min(240, width - 16);
        List<String> rows = wrap(font, text, wide);
        boolean overflow = false;
        for (String row : rows) {
            if (font.width(row) > width - 16) {
                overflow = true;
                break;
            }
        }
        if (overflow) {
            rows = wrap(font, text, 120);
        }
        int y = 30;
        for (String row : rows) {
            g.drawString(font, row, 8, y, 0xFFFFFF);
            y += 12;
        }
        super.render(g, mouseX, mouseY, partialTick);
    }
}

